#!/usr/bin/env python3
"""Self-contained NETFORGE static site with an optional local ICMP ping endpoint.

Run: python netforge_local.py
Open: http://127.0.0.1:8765
Requires Python 3.10+ and only the standard library.
"""
from __future__ import annotations
import argparse, base64, ipaddress, json, mimetypes, re, subprocess, sys
import webbrowser, zlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote, urlsplit

PAYLOAD = ""
ASSETS = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))

def json_bytes(value):
    return json.dumps(value, ensure_ascii=False).encode("utf-8")

def ping_address(value):
    address = ipaddress.ip_address(value.strip())
    if sys.platform == "win32":
        command = ["ping", "-n", "1", "-w", "1800"]
        if address.version == 6:
            command.insert(1, "-6")
    else:
        command = ["ping", "-6" if address.version == 6 else "-4", "-c", "1", "-W", "2"]
    command.append(str(address))
    try:
        result = subprocess.run(command, capture_output=True, text=True, timeout=2.5, check=False)
    except subprocess.TimeoutExpired:
        return {"ip": str(address), "reachable": False, "latency_ms": None, "message": "Ping timed out"}
    except OSError:
        return {"ip": str(address), "reachable": False, "latency_ms": None, "message": "Ping is unavailable on this system"}
    output = (result.stdout + "\n" + result.stderr).strip()
    match = re.search(r"time[=<]\s*([\d.]+)\s*ms", output, re.I)
    latency = float(match.group(1)) if match else (0.5 if re.search(r"time<1\s*ms", output, re.I) else None)
    return {"ip": str(address), "reachable": result.returncode == 0, "latency_ms": latency}

class Handler(BaseHTTPRequestHandler):
    def reply(self, status, data, content_type="application/json; charset=utf-8"):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        path = unquote(urlsplit(self.path).path)
        if path == "/":
            path = "/index.html"
        if path == "/netforge_local.py":
            try:
                data = Path(__file__).read_bytes()
            except OSError:
                return self.reply(404, b"Not found", "text/plain; charset=utf-8")
            return self.reply(200, data, "text/x-python; charset=utf-8")
        name = path.lstrip("/")
        if name not in ASSETS:
            return self.reply(404, b"Not found", "text/plain; charset=utf-8")
        mime = mimetypes.guess_type(name)[0] or "application/octet-stream"
        if mime.startswith("text/") or mime in ("application/javascript", "application/json"):
            mime += "; charset=utf-8"
        return self.reply(200, ASSETS[name].encode("utf-8"), mime)

    def do_POST(self):
        if urlsplit(self.path).path != "/api/ping":
            return self.reply(404, json_bytes({"detail": "Not found"}))
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length < 1 or length > 4096:
                raise ValueError("Invalid request size")
            data = json.loads(self.rfile.read(length))
            result = ping_address(str(data.get("ip", "")))
            return self.reply(200, json_bytes(result))
        except ValueError as exc:
            return self.reply(400, json_bytes({"detail": str(exc)}))
        except Exception:
            return self.reply(500, json_bytes({"detail": "Ping request could not be completed"}))

    def log_message(self, fmt, *args):
        print("%s - %s" % (self.log_date_time_string(), fmt % args))

def main():
    parser = argparse.ArgumentParser(description="Run the self-contained NETFORGE website locally.")
    parser.add_argument("--port", type=int, default=8765)
    parser.add_argument("--no-open", action="store_true", help="Do not open a browser tab")
    args = parser.parse_args()
    server = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    url = "http://127.0.0.1:%d" % args.port
    print("NETFORGE is running at " + url)
    print("Press Ctrl+C to stop.")
    if not args.no_open:
        try:
            webbrowser.open(url)
        except Exception:
            pass
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopping NETFORGE.")
    finally:
        server.server_close()

if __name__ == "__main__":
    main()

